    private static func parseRoutes(_ encoded: String) -> [Int: [String]] {
        var out: [Int: [String]] = [:]
        for entry in encoded.split(separator: "|") {
            let parts = entry.split(separator: "=")
            guard parts.count == 2, let n = Int(parts[0]) else { continue }
            out[n] = parts[1].split(separator: ",").map(String.init)
        }
        return out
    }

