    private static let routeTableStraight = parseRoutes(routesStraight)

    /// The route THRØ shows for `remaining`, or nil when there is no finish.
    public static func route(_ remaining: Int, _ outRule: OutRule) -> [String]? {
        switch outRule {
        case .double: return routeTableDouble[remaining]
        case .master: return routeTableMaster[remaining]
        case .straight: return routeTableStraight[remaining]
        }
    }

