    private static let openingStraight = opening(maxOpeningStraight, unopenableStraight)

    public static func openingTotals(_ inRule: InRule) -> Set<Int> {
        switch inRule {
        case .double: return openingDouble
        case .master: return openingMaster
        case .straight: return openingStraight
        }
    }

    private static func opening(_ max: Int, _ unopenable: Set<Int>) -> Set<Int> {
        var out = Set<Int>(minimumCapacity: max)
        for v in 1...max where !unopenable.contains(v) && !impossibleVisitTotals.contains(v) {
            out.insert(v)
        }
        return out
    }

    /// The floor is the rule's own: under straight-out a single 1 finishes.
    private static func build(_ min: Int, _ max: Int, _ bogeys: Set<Int>) -> Set<Int> {
        var out = Set<Int>(minimumCapacity: max)
        for v in min...max where !bogeys.contains(v) { out.insert(v) }
        return out
    }
